#include <bits/stdc++.h>
using namespace std;
struct Graph{string name; int n; vector<pair<int,int>> e;};
Graph heawood(){ Graph g{"Heawood",14,{}}; for(int j=0;j<7;j++)for(int d:{0,1,3}){int i=(j+d)%7;g.e.push_back({i,7+j});} return g;}
Graph mobius(){Graph g{"MobiusKantor",16,{}};for(int i=0;i<8;i++){g.e.push_back({i,(i+1)%8});g.e.push_back({i,8+i});g.e.push_back({8+i,8+(i+3)%8});} return g;}
Graph pappus(){Graph g{"Pappus",18,{}};for(int x=0;x<3;x++)for(int y=0;y<3;y++)for(int m=0;m<3;m++){int b=(y-m*x+9)%3;g.e.push_back({3*x+y,9+3*m+b});}return g;}
Graph desargues(){Graph g{"Desargues",20,{}};for(int i=0;i<10;i++){g.e.push_back({i,(i+1)%10});g.e.push_back({i,10+i});g.e.push_back({10+i,10+(i+3)%10});}return g;}
struct Stats{unsigned long long total=0, dominated=0, cuts=0, both=0; map<string,long long> shape; vector<unsigned long long> opt;};
bool cut(const Graph&g,unsigned long long mask,vector<int> *shape=nullptr){int n=g.n; int par[40];for(int i=0;i<n;i++)par[i]=i;auto root=[&](int x){while(par[x]!=x)x=par[x];return x;};for(int i=0;i<(int)g.e.size();i++) if(!(mask>>i&1)){auto[u,v]=g.e[i];int a=root(u),b=root(v);par[a]=b;} int cnt[40]={}; for(int i=0;i<n;i++)cnt[root(i)]++;int k=0; if(shape)shape->clear();for(int i=0;i<n;i++)if(cnt[i]){k++;if(shape)shape->push_back(cnt[i]);}if(shape)sort(shape->begin(),shape->end());return k>1;}
bool edom(const Graph&g,unsigned long long mask){unsigned long long touched=0;for(int i=0;i<(int)g.e.size();i++)if(mask>>i&1){auto[u,v]=g.e[i];touched|=1ULL<<u | 1ULL<<v;}for(auto[u,v]:g.e)if((touched>>u&1)==0 && (touched>>v&1)==0)return false;return true;}
Stats examine(const Graph &g,int k,bool collect){Stats s;int m=g.e.size(); if(k>m)return s;unsigned long long bits=(1ULL<<k)-1,lim=1ULL<<m;while(bits<lim){s.total++;bool dom=edom(g,bits);if(dom)s.dominated++;bool c=cut(g,bits);if(c)s.cuts++;if(dom&&c){s.both++;if(collect){vector<int> sh;cut(g,bits,&sh);string z="";for(auto v:sh)z+=to_string(v)+",";s.shape[z]++;s.opt.push_back(bits);}} unsigned long long x=bits&-bits,y=bits+x;bits=(((bits&~y)/x)>>1)|y;}return s;}
int main(int argc,char**argv){string name=argc>1?argv[1]:"Heawood";Graph g=name=="Heawood"?heawood():name=="MobiusKantor"?mobius():name=="Pappus"?pappus():desargues(); int stop=argc>2?atoi(argv[2]):10;cerr<<"Graph "<<g.name<<" n="<<g.n<<" m="<<g.e.size()<<"\n";cout<<"GRAPH "<<g.name<<" "<<g.n<<" "<<g.e.size()<<"\n";for(int k=1;k<=stop;k++){auto s=examine(g,k,true);cerr<<"k="<<k<<" subsets="<<s.total<<" dom="<<s.dominated<<" cut="<<s.cuts<<" joint="<<s.both<<"\n";cout<<"LEVEL "<<k<<" "<<s.total<<" "<<s.dominated<<" "<<s.cuts<<" "<<s.both<<"\n";if(s.both){cout<<"SHAPES";for(auto[z,c]:s.shape)cout<<" ["<<z<<":"<<c<<"]";cout<<"\n";cout<<"EDGE_LIST";for(auto[u,v]:g.e)cout<<" ("<<u<<","<<v<<")";cout<<"\n";cout<<"SETS";for(auto b:s.opt)cout<<" "<<b;cout<<"\n";break;}}}
